#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    half* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int groups
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_h_idx = blockIdx.z;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_h_idx >= output_height) {
        return;
    }

    int tid = threadIdx.x;
    int total_threads = blockDim.x;

    // Each thread processes multiple elements if needed
    for (int out_w_idx = tid; out_w_idx < output_width; out_w_idx += total_threads) {
        // Initialize accumulator
        float acc = 0.0f;

        // Calculate input channel index for group convolution
        int group_size_in = in_channels / groups;
        int group_size_out = out_channels / groups;
        int group_idx = out_ch_idx / group_size_out;
        int in_ch_start = group_idx * group_size_in;
        int in_ch_end = in_ch_start + group_size_in;

        // Loop over input channels and kernel
        for (int in_ch_idx = in_ch_start; in_ch_idx < in_ch_end; ++in_ch_idx) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    // Calculate input position
                    int input_h = out_h_idx * stride - padding + kh;
                    int input_w = out_w_idx * stride - padding + kw;

                    // Check bounds
                    if (input_h >= 0 && input_h < input_height && input_w >= 0 && input_w < input_width) {
                        // Get weight index
                        int weight_idx = out_ch_idx * in_channels * kernel_size * kernel_size +
                                         in_ch_idx * kernel_size * kernel_size +
                                         kh * kernel_size + kw;

                        // Get input index
                        int input_idx = batch_idx * in_channels * input_height * input_width +
                                        in_ch_idx * input_height * input_width +
                                        input_h * input_width + input_w;

                        // Accumulate
                        acc += __half2float(weight[weight_idx]) * __half2float(input[input_idx]);
                    }
                }
            }
        }

        // Write result
        int output_idx = batch_idx * out_channels * output_height * output_width +
                         out_ch_idx * output_height * output_width +
                         out_h_idx * output_width + out_w_idx;
        output[output_idx] = __float2half(acc);
    }
}

// Wrapper function for launching kernel
extern "C" void launch_conv_transpose2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int groups
