        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # Initialize weights
        self.weight = torch.nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size, kernel_size, dtype=torch.float16)
        )
        if bias:
            self.bias_param = torch.nn.Parameter(torch.randn(out_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias_param', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, input_height, input_width = x.shape

        # Calculate output dimensions
        output_height = (input_height - 1) * self.stride - 2 * self.padding + self.kernel_size
        output_width = (input_width - 1) * self.stride - 2 * self.padding + self.kernel_size

        # Allocate output tensor
        output = torch.empty(
            batch_size, self.out_channels, output_height, output_width,
            dtype=torch.float16, device=x.device
        )

        # Launch CUDA kernel
        conv_transpose2d_ext.launch_conv_transpose2d(
            x.contiguous().data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            self.out_channels,
            input_height,
            input_width,
            output_height,
            output_width,
            self.kernel_size,
            self.stride,
            self.padding,
            self.groups
        )

        # Add bias if present
        if self.bias_param is not None:
            output += self.bias_param.view(1, -1, 1, 1)

        return output
